  // Visible light beams (Point Light > Beam): additive corona billboards +
  // optional cone shafts at the light source, following the light's runtime
  // state (flicker / Set Light / visibility). Drawn at the end of
  // renderScene so DoF and god rays treat them as scene light.
  struct LightBeam {
    int objIndex = -1;
    int kind = 0;  // 1 glow, 2 glow + cone
    BagArray<Tyra::Vec4> coronaVerts, coronaSts, coneVerts;
    BagArray<Tyra::Color> coneColors;
    Tyra::Color coronaColor;
    Tyra::M4x4 mat;  // identity - geometry is world space
    std::unique_ptr<Tyra::StaPipInfoBag> coronaInfo, coneInfo;
    std::unique_ptr<Tyra::StaPipColorBag> coronaColorBag, coneColorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> coronaTexBag;
    std::unique_ptr<Tyra::StaPipBag> coronaBag, coneBag;
    // The cone shaft is a pure function of the lamp's position and radius -
    // both static for an authored lamp - and its two colours of the lamp
    // colour. Only the flicker's additiveBlendFix moves. Remember that key so
    // 24 vertices, 24 colours and 16 transcendental calls per visible cone per
    // frame do not run again merely because the brightness breathed, and so
    // the bag's bboxVersion stops being stamped on a shaft that did not move
    // (a stamp costs the retained-command block a rebuild - STAPIPMISS). The
    // LightPool below caches its receiver patch for the same reason (1.122.2).
    bool coneValid = false;
    float coneKeyX = 0.0F, coneKeyY = 0.0F, coneKeyZ = 0.0F;
    float coneKeyRadius = 0.0F;
    float coneKeyR = 0.0F, coneKeyG = 0.0F, coneKeyB = 0.0F;
  };
  std::vector<LightBeam> lightBeams;
  // ONE bag for every visible corona and one for every cone shaft, rebuilt
  // per call (docs/ee-submission-rearchitecture.md, "Round four"). A beam used
  // to be two StaPip submissions
  // of 6 and 24 vertices, each paying the whole per-bag path - bounds,
  // uniforms, dispatch - for a quad: 0.86 ms of Motor District's garage night
  // on a physical PS2. The per-lamp brightness that rode each bag's additive
  // FIX is folded into the vertex colours instead (additive, so
  // Cs*k*128/128 + Cd is the same light), and a batch draws at FIX 128.
  //
  // One batch PER CALL IN A FRAME (the main view, then every portal view):
  // the chain the first call submits REFs its arrays, so a second call may
  // not refill them before VIF1 has read them. The previous frame's slots are
  // safe to reuse - RendererCore::endFrame waits for the whole VIF1 queue.
  // Held by pointer so the addresses the bags point at never move.
  struct BeamBatch {
    Tyra::M4x4 mat;
    BagArray<Tyra::Vec4> coronaVerts, coronaSts, coneVerts;
    BagArray<Tyra::Color> coronaColors, coneColors;
    std::unique_ptr<Tyra::StaPipInfoBag> coronaInfo, coneInfo;
    std::unique_ptr<Tyra::StaPipColorBag> coronaColorBag, coneColorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> coronaTexBag;
    std::unique_ptr<Tyra::StaPipBag> coronaBag, coneBag;
  };
  std::vector<std::unique_ptr<BeamBatch>> beamBatches;
  int beamBatchCall = 0;  // reset by loop() every frame
  BeamBatch& beamBatchForCall();
  Tyra::Texture* beamCoronaTex = nullptr;
  void setupLightBeams();            // per scene load
  void updateAndRenderLightBeams(const Tyra::Vec4* viewEye = nullptr,
                                const Tyra::Vec4* viewAt = nullptr, int portal = -1);
  // Ground pools of the DYNAMIC point lights: the terrain opts out of the
  // per-chunk light pick (hard seams at chunk borders), so each dynamic
  // light paints its pool as a smooth additive terrain-conforming patch
  // instead - same corona sprite, same flicker breathing.
  struct LightPool {
    int objIndex = -1;
    BagArray<Tyra::Vec4> verts, sts;
    Tyra::Color color;
    // Scene-light receiver geometry is static until the authored light moves.
    // Remember the patch key so the expensive road/terrain height queries do
    // not run again merely because its brightness flickered.
    bool patchValid = false;
    float patchCx = 0.0F, patchCz = 0.0F, patchR = 0.0F, patchLift = 0.0F;
    // A scene SPOT's landing and projective STQ, keyed on the light's pose,
    // reach and cone (position, rotation, lightRadius, lightSpotAngle): a
    // lamp that has not moved keeps both, so its cone is not marched to the
    // ground again and its STQ array keeps its content stamp - the bag
    // replays its baked stream instead of re-staging every frame.
    float spotKey[8] = {};
    bool spotKeyValid = false;
    float spotHit = -1.0F;
    // The flashlight's SECOND patch, for the wall its beam is touching. Both
    // are drawn every frame and the depth buffer decides where each shows,
    // because a beam sweeping from the floor up a wall really does light both
    // at once - one patch had to teleport from one to the other, and that read
    // as the light blinking off and on again. Its own buffers, never a second
    // pass over the first: the DMA may still be reading them.
    BagArray<Tyra::Vec4> wVerts, wSts;
    // Per-vertex Gouraud colors, torch patches only: the projective STQ has
    // no distance falloff of its own - along the beam's axis the mapping
    // converges to the gobo's hot centre at ANY range, so a grazing pool lit
    // its far reaches at full strength (bright trapezoids on every rise the
    // beam touched, reported from the console). The reach falloff rides the
    // vertex color instead, which the GS interpolates per pixel.
    BagArray<Tyra::Color> colors, wColors;
    Tyra::Color wColor;
    std::unique_ptr<Tyra::StaPipInfoBag> wInfo;
    std::unique_ptr<Tyra::StaPipColorBag> wColorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> wTexBag;
    std::unique_ptr<Tyra::StaPipBag> wBag;
    // Shadow volumes (FLASH_SHADOW_VOLUMES, docs/flashlight.md): the
    // silhouette-extruded volumes, split by CAMERA facing. With the count
    // target up (alphaMask.countReady) front faces ADD +32 into it and back
    // faces SUBTRACT it back - TestOnly vs the scene depth - and one resolve
    // per caster ORs count>0 into the destination-alpha mask; without it the
    // convex sub-box fallback writes the alpha bit directly (0x80 / 0).
    BagArray<Tyra::Vec4> volFront, volBack;
    Tyra::Color volSetColor, volClrColor;
    std::unique_ptr<Tyra::StaPipInfoBag> volInfo, volClrInfo;
    std::unique_ptr<Tyra::StaPipColorBag> volSetBagC, volClrBagC;
    std::unique_ptr<Tyra::StaPipBag> volSetBag, volClrBag;
    // The carving spot light's RECEIVER pass (docs/shadows.md): its light on
    // the solids its cone touches, drawn a second time per pixel through the
    // mask - the torch's wall pass on a scene lamp. Its own buffers, on the
    // torch's pool like the volume buffers: one spot carves per frame.
    BagArray<Tyra::Vec4> sWVerts, sWSts;
    BagArray<Tyra::Color> sWColors;
    Tyra::Color sWColor;
    std::unique_ptr<Tyra::StaPipInfoBag> sWInfo;
    std::unique_ptr<Tyra::StaPipColorBag> sWColorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> sWTexBag;
    std::unique_ptr<Tyra::StaPipBag> sWBag;
    Tyra::M4x4 mat;
    std::unique_ptr<Tyra::StaPipInfoBag> info;
    std::unique_ptr<Tyra::StaPipColorBag> colorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> texBag;
    std::unique_ptr<Tyra::StaPipBag> bag;
  };
  std::vector<LightPool> lightPools;
  // Scene spot pools that are not carving a shadow this frame, drawn as ONE
  // bag (docs/flashlight.md, "One bag for the still pools"): their verts and
  // STQs copied end to end, each lamp's colour times its FIX in the vertex
  // colours, FIX 128 for the batch. Rewritten only when a member or one of
  // its source stamps changes, so a still district replays it baked.
  struct PoolBatch {
    BagArray<Tyra::Vec4> verts, sts;
    BagArray<Tyra::Color> colors;
    Tyra::M4x4 mat;
    std::unique_ptr<Tyra::StaPipInfoBag> info;
    std::unique_ptr<Tyra::StaPipColorBag> colorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> texBag;
    std::unique_ptr<Tyra::StaPipBag> bag;
    std::vector<const LightPool*> members;
    std::vector<float> memberFix;
    std::vector<unsigned int> key, lastKey;
  } poolBatch_;
  void poolBatchAdd(const LightPool& b, float fix);
  void poolBatchFlush();
  // Optional custom sprite for the flashlight's pool (Player > Flashlight >
  // Pool texture). Cached by path - a scene switch must not re-add the same
  // texture to the repository.
  Tyra::Texture* flashPoolTex = nullptr;
  std::string flashPoolTexPath;
  // ...and the built-in one it falls back to: the baked gobo
  // (res/hud/flashlight-gobo.png, loaded in buildScene when FLASHLIGHT_USED).
  Tyra::Texture* flashGoboTex = nullptr;
  // The last entry (objIndex -1) is the camera flashlight's: per-VERTEX
  // lighting cannot draw a spot smaller than the mesh tessellation, so
  // looking down at your own feet lit nothing (the cone footprint is
  // smaller than a terrain cell). That patch is PROJECTED from the beam's
  // own frustum instead, so its shape comes from the gobo texture and not
  // from the terrain's vertex grid (docs/flashlight.md).
  void setupLightPools();            // per scene load
  void updateAndRenderLightPools();  // per frame, before the shadows
  bool buildPoolPatch(LightPool& b, float cx, float cz, float r, float lift);
  // Blob shadows (BLOB_SHADOWS): a soft dark terrain-conforming grid under
  // each moving object (third-person avatar, animated models, physics
  // objects), fading out as the object rises. Per-caster arrays - the DMA
  // may still be reading a submitted patch, so casters never share buffers.
  struct BlobShadow {
    int objIndex = -1;
    bool shaped = false;
    float shapeX = 0.0F, shapeZ = 0.0F;  // baked local footprint, if known
    std::string texPath;
    Tyra::Texture* texture = nullptr;
    BagArray<Tyra::Vec4> verts, sts;
    Tyra::Color color;
    Tyra::M4x4 mat;
    // The caster's transform the patch was last built for (position,
    // rotation, scale). A caster that has not moved keeps its patch, its
    // content stamp and its bboxVersion, so the bag stays baked - see
    // updateAndRenderBlobShadows. `keyHidden`: that build faded to nothing.
    float key[9] = {};
    bool keyValid = false, keyHidden = false;
    Tyra::Vec4 cullMin, cullMax;  // the footprint box that build was culled by
    std::unique_ptr<Tyra::StaPipInfoBag> info;
    std::unique_ptr<Tyra::StaPipColorBag> colorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> texBag;
    std::unique_ptr<Tyra::StaPipBag> bag;
  };
  std::vector<BlobShadow> blobShadows;
  Tyra::Texture* blobShadowTex = nullptr;
  void setupBlobShadows();            // per scene load
  void updateAndRenderBlobShadows();  // per frame, end of renderScene
  // Projected silhouette shadows (per-object "Cast shadow"): the caster's
  // existing bags re-render into a small VRAM target from a light camera,
  // then a terrain patch under it samples the silhouette (renderProjShadows).
  struct ProjShadow {
    BagArray<Tyra::Vec4> verts, sts;  // receiver patch (terrain-conforming)
    Tyra::Color color;
    // The WALL copy (docs/flashlight.md, "The shadow"): when the torch is the
    // light that threw this slot's silhouette, the geometry the shadow ray
    // lands on is re-rendered with the silhouette sampled through the light's
    // view-proj - the same second-pass trick the torch's own light uses, so a
    // caster in the beam paints its shadow ON the wall behind it. Own buffers:
    // the DMA may still be reading the ground patch's.
    BagArray<Tyra::Vec4> wallVerts, wallSts;
    Tyra::Color wallColor;
    std::unique_ptr<Tyra::StaPipInfoBag> wallInfo;
    std::unique_ptr<Tyra::StaPipColorBag> wallColorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> wallTexBag;
    std::unique_ptr<Tyra::StaPipBag> wallBag;
    Tyra::M4x4 mat;
    std::unique_ptr<Tyra::StaPipInfoBag> info;
    std::unique_ptr<Tyra::StaPipColorBag> colorBag;
    std::unique_ptr<Tyra::StaPipTextureBag> texBag;
    std::unique_ptr<Tyra::StaPipBag> bag;
    // WHO this slot is showing, and how far its cross-dissolve has got.
    // The set used to be re-derived from scratch every frame - "the four
    // casters nearest the camera", sorted, nothing remembered - so two
    // casters at nearly equal distance traded a slot frame to frame, and a
    // caster that lost one went from full alpha to nothing between two
    // frames. A slot is HELD now (renderProjShadows, "which four casters
    // hold the slots"): `leaving` + `fade` are the hand-over dissolve,
    // `want`/`wantFrames` the challenger that has to out-stay the
    // hysteresis, `barren` how long the holder has drawn nothing.
    int occupant = -1;
    float fade = 0.0F;
    bool leaving = false;
    int barren = 0;
    int want = -1;
    int wantFrames = 0;
    // ...and which LIGHT threw this slot's silhouette last frame, on the
    // same terms: the source is picked by score, and a torch walking past a
    // lamp crosses that line twice in a couple of steps - which swings the
    // silhouette to the other side of the prop and back. 0 = the scene
    // sun/moon, 1 = the player's torch, 2 = a placed light at lightPos.
    bool lightHeld = false;
    int lightKind = 0;
    float lightPos[3] = {0.0F, 0.0F, 0.0F};
    int lightWantFrames = 0;
  };
  std::vector<ProjShadow> projShadows;  // one per engine slot in use
  std::vector<int> projCasters;         // authored caster object indices
  void setupProjShadows();   // per scene load
  void renderProjShadows();  // per frame, end of renderScene
  // The floor a shadow lands on. Terrain OR geometry: an indoor level's real
  // floor is boxes metres above the heightfield, and a patch built on the
  // heightfield alone ends up underneath it (see projCollectReceivers).
  void projCollectReceivers(float cx, float cz, float reach, float yMax);
  float projSurfaceAt(float x, float z);
  // ...and the same objects as full boxes, walls included, for the flashlight's
  // pool: shine a beam at a wall and the light belongs ON the wall, which the
  // receiver list cannot say (it drops anything taller than the caster) and the
  // marched column cannot either (it would put the light on the wall's top).
  // projWallHit returns the nearest face the beam enters through: t along the
  // ray, which axis the face is perpendicular to, which side of the box, and
  // the box itself so the patch can be clipped to that face.
  void projCollectBoxes(float cx, float cz, float reach);
  bool projWallHit(const Tyra::Vec4& from, float dx, float dy, float dz,
                   float maxT, float& outT, int& outAxis, float& outSign,
                   struct ProjBox& outBox);
  // The objects whose own per-vertex flashlight cone is switched OFF because the
  // projected pool is doing that job on them (big flat boxes the cone would
  // simply flood). Rebuilt each frame by updateFlashSpotOff.
  std::vector<int> flashSpotOffList;
  // ...fed by the pool pass: the cone receivers of this frame (objects the
  // beam cone touches), whose per-vertex cone the projected light replaces.
  std::vector<int> flashSpotExtra;
  void updateFlashSpotOff();
  void setFlashSpotOff(int obj, bool lit);
  // The objects the carving spot light lit through its receiver pass this
  // frame: their per-vertex slot must skip THAT lamp (dynLightSkipSlot), or
  // the wall is lit twice and the carved shadow darkens only half of it.
  // Re-applied every frame, like the torch's list; reset when the lamp moves
  // on. The lone-batch rule is setFlashSpotOff's.
  std::vector<int> spotSkipList;
  std::unique_ptr<Tyra::StaPipInfoBag> batchSkipInfoBag;
  void setDynLightSkip(int obj, int slot);

  // Runtime texts (font_data.gen.hpp): one slot per Display Text node, drawn
  // glyph by glyph from a font atlas because the string is only known now.
  void updateAndRenderDynTexts();
  std::vector<signed char> dynTextReq;   // ScriptContext::dynTextRequest
  std::vector<float> dynTextDur;         // ScriptContext::dynTextDuration
  std::vector<char> dynTextBuf;          // DYN_TEXT_COUNT * DYN_TEXT_LEN
  std::vector<unsigned char> dynTextOn;  // visible this frame
  std::vector<float> dynTextTimer;
  // One caret per menu: a sheet may point at its own image, and a texture link
  // belongs to a sprite id. Menus that say nothing share the built-in file, so
  // the repository hands them all the same Texture and VRAM does not move.
  std::vector<Tyra::Sprite> menuCursorSprites;
  Tyra::Sprite menuCursorSprite;
  Tyra::Sprite menuDimSprite;  // fullscreen dim under pausing menus
  int gameMenuIndex = -1;
  int gameMenuCursor = 0;
  // First visible row of a scrolling list, and the seconds the open transition
  // and the caret have been running (docs/menu-styles.md - motion is sprite
  // properties, so this is all the state it needs).
  int gameMenuScroll = 0;
  // The menu that is closing: it keeps drawing while its close transition plays,
  // because a panel that vanishes on the frame the button was pressed is exactly
  // the thing the transition exists to avoid.
  int gameMenuClosing = -1;
  float gameMenuCloseT = 0.0F;
  float gameMenuScrollShown = 0.0F;  // eased scroll position, in rows
  float gameMenuValueFlash = 0.0F;   // seconds left of the value flash
  float gameMenuClock = 0.0F;        // seconds a menu has been open (the loops)
  float gameMenuOpenT = 0.0F;
