static const char* TPL_RUN_PS1 = R"($ConfigFile = Join-Path $PSScriptRoot './windows-pcsx2.ps1'
. $ConfigFile

RunPCSX2
)";

static const char* TPL_PCSX2_PS1 = R"PS1(# =======================
$CUSTOM_PCSX2_PATH = "" # "D:/My/Path/To/PCSX2"
# =======================

function GetTargetELFName {
    return (Select-String -Path './Makefile' -Pattern "[^ ]*.elf").Matches.Value
}

function FindPCSX2Directory {
    if (-not [string]::IsNullOrEmpty($CUSTOM_PCSX2_PATH)) {
        return $CUSTOM_PCSX2_PATH
    }
    else {
        $pcsx2Path = "${Env:ProgramFiles}/PCSX2"
        $pcsx2Pathx86 = "${Env:ProgramFiles(x86)}/PCSX2"

        if (Test-Path -Path $pcsx2Path) {
            return $pcsx2Path
        }
        elseif (Test-Path -Path $pcsx2Pathx86) {
            return $pcsx2Pathx86
        }
        else {
            throw "PCSX2 directory not found!"
        }
    }
}

function FindPCSX2Executable {
    param ([string]$directory)

    foreach ($name in 'pcsx2.exe', 'pcsx2-qt.exe') {
        if (Test-Path -Path (Join-Path $directory $name)) { return $name }
    }
    throw "PCSX2 executable not found in: $directory!"
}

function RunPCSX2 {
    $dirPath = FindPCSX2Directory
    $isNewVersion = Test-Path -Path "$dirPath/qt.conf"
    $executableName = FindPCSX2Executable -directory $dirPath
    $executableNameWithoutExt = (Split-Path $executableName -Leaf).Split('.')[0]
    $targetFileName = "$PWD/bin/$(GetTargetELFName)"

    Stop-Process -Name $executableNameWithoutExt -ErrorAction 'SilentlyContinue'

    if ($isNewVersion) {
        Start-Process -FilePath "$dirPath/$executableName" -ArgumentList "-elf", $targetFileName
    }
    else {
        Start-Process -FilePath "$dirPath/$executableName" -ArgumentList "--elf=$targetFileName"
    }
}
)PS1";

// The POSIX twin of run.ps1 + windows-pcsx2.ps1, kept as one file because
// there is no equivalent of the two-file "edit the config, keep the runner"
// split to preserve here - the emulator path is a single variable at the top.
// Both exist in every project regardless of the authoring OS: a project is
// portable, so the helper for the OTHER machine has to be there when someone
// clones it.
static const char* TPL_RUN_SH = R"SH(#!/usr/bin/env bash
# Runs the built ELF in PCSX2, outside the editor. Set PCSX2 below (or export
# PCSX2=/path/to/pcsx2) when yours is not on PATH / not a flatpak.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

PCSX2="${PCSX2:-}"
if [ -z "$PCSX2" ]; then
    for c in pcsx2-qt pcsx2; do
        command -v "$c" >/dev/null 2>&1 && PCSX2="$c" && break
    done
fi
if [ -z "$PCSX2" ] && command -v flatpak >/dev/null 2>&1 &&
   flatpak info net.pcsx2.PCSX2 >/dev/null 2>&1; then
    PCSX2="flatpak run net.pcsx2.PCSX2"
fi
if [ -z "$PCSX2" ]; then
    for c in "$HOME"/Applications/*.AppImage "$HOME"/Downloads/*.AppImage; do
        case "$(basename "$c")" in [Pp][Cc][Ss][Xx]2*) PCSX2="$c"; break;; esac
    done
fi
if [ -z "$PCSX2" ]; then
    echo "PCSX2 not found - install it or set PCSX2=/path/to/pcsx2" >&2
    exit 1
fi

ELF="bin/$(grep -oE '[^ ]*\.elf' Makefile | head -1)"
[ -f "$ELF" ] || { echo "$ELF not found - build the project first." >&2; exit 1; }

pkill -x pcsx2-qt >/dev/null 2>&1 || true
pkill -x pcsx2 >/dev/null 2>&1 || true
exec $PCSX2 -elf "$PWD/$ELF"
)SH";

